37	/**
38	 * Mostly used as a facade for all Petclinic controllers
39	 * Also a placeholder for @Transactional and @Cacheable annotations
40	 *
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Service
45	public class ClinicServiceImpl implements ClinicService {
46	
47	    private final PetRepository petRepository;
48	    private final VetRepository vetRepository;
49	    private final OwnerRepository ownerRepository;
50	    private final VisitRepository visitRepository;
51	    private final SpecialtyRepository specialtyRepository;
52	    private final PetTypeRepository petTypeRepository;
53	
54	    public ClinicServiceImpl(
55	        PetRepository petRepository,
56	        VetRepository vetRepository,
57	        OwnerRepository ownerRepository,
58	        VisitRepository visitRepository,
59	        SpecialtyRepository specialtyRepository,
60	        PetTypeRepository petTypeRepository) {
61	        this.petRepository = petRepository;
62	        this.vetRepository = vetRepository;
63	        this.ownerRepository = ownerRepository;
64	        this.visitRepository = visitRepository;
65	        this.specialtyRepository = specialtyRepository;
66	        this.petTypeRepository = petTypeRepository;
67	    }
68	
69	    @Override
70	    @Transactional(readOnly = true)
71	    public Collection<Pet> findAllPets() throws DataAccessException {
72	        return petRepository.findAll();
73	    }
74	
75	    @Override
76	    @Transactional(readOnly = true)
77	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
78	        return petRepository.findAll(pageable);
79	    }
80	
81	    @Override
82	    @Transactional
83	    public void deletePet(Pet pet) throws DataAccessException {
84	        petRepository.delete(pet);
85	    }
86	
87	    @Override
88	    @Transactional(readOnly = true)
89	    public Visit findVisitById(int visitId) throws DataAccessException {
90	        return findEntityById(() -> visitRepository.findById(visitId));
91	    }
92	
93	    @Override
94	    @Transactional(readOnly = true)
95	    public Collection<Visit> findAllVisits() throws DataAccessException {
96	        return visitRepository.findAll();
97	    }
98	
99	    @Override
100	    @Transactional
101	    public void deleteVisit(Visit visit) throws DataAccessException {
102	        visitRepository.delete(visit);
103	    }
104	
105	    @Override
106	    @Transactional(readOnly = true)
107	    public Vet findVetById(int id) throws DataAccessException {
108	        return findEntityById(() -> vetRepository.findById(id));
109	    }
110	
111	    @Override
112	    @Transactional(readOnly = true)
113	    public Collection<Vet> findAllVets() throws DataAccessException {
114	        return vetRepository.findAll();
115	    }
116	
117	    @Override
118	    @Transactional
119	    public void saveVet(Vet vet) throws DataAccessException {
120	        vetRepository.save(vet);
121	    }
122	
123	    @Override
124	    @Transactional
125	    public void deleteVet(Vet vet) throws DataAccessException {
126	        vetRepository.delete(vet);
127	    }
128	
129	    @Override
130	    @Transactional(readOnly = true)
131	    public Collection<Owner> findAllOwners() throws DataAccessException {
132	        return ownerRepository.findAll();
133	    }
134	
135	    @Override
136	    @Transactional(readOnly = true)
137	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
138	        if (lastName != null) {
139	            return ownerRepository.findByLastName(lastName, pageable);
140	        }
141	        return ownerRepository.findAll(pageable);
142	    }
143	
144	    @Override
145	    @Transactional
146	    public void deleteOwner(Owner owner) throws DataAccessException {
147	        ownerRepository.delete(owner);
148	    }
149	
150	    @Override
151	    @Transactional(readOnly = true)
152	    public PetType findPetTypeById(int petTypeId) {
153	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
154	    }
155	
156	    @Override
157	    @Transactional(readOnly = true)
158	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
159	        return petTypeRepository.findAll();
160	    }
161	
162	    @Override
163	    @Transactional
164	    public void savePetType(PetType petType) throws DataAccessException {
165	        petTypeRepository.save(petType);
166	    }
167	
168	    @Override
169	    @Transactional
170	    public void deletePetType(PetType petType) throws DataAccessException {
171	        petTypeRepository.delete(petType);
172	    }
173	
174	    @Override
175	    @Transactional(readOnly = true)
176	    public Specialty findSpecialtyById(int specialtyId) {
177	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
178	    }
179	
180	    @Override
181	    @Transactional(readOnly = true)
182	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
183	        return specialtyRepository.findAll();
184	    }
185	
186	    @Override
187	    @Transactional
188	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
189	        specialtyRepository.save(specialty);
190	    }
191	
192	    @Override
193	    @Transactional
194	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
195	        specialtyRepository.delete(specialty);
196	    }
197	
198	    @Override
199	    @Transactional(readOnly = true)
200	    public Collection<PetType> findPetTypes() throws DataAccessException {
201	        return petRepository.findPetTypes();
202	    }
203	
204	    @Override
205	    @Transactional(readOnly = true)
206	    public Owner findOwnerById(int id) throws DataAccessException {
207	        return findEntityById(() -> ownerRepository.findById(id));
208	    }
209	
210	    @Override
211	    @Transactional(readOnly = true)
212	    public Pet findPetById(int id) throws DataAccessException {
213	        return findEntityById(() -> petRepository.findById(id));
214	    }
215	
216	    @Override
217	    @Transactional
218	    public void savePet(Pet pet) throws DataAccessException {
219	        pet.setType(findPetTypeById(pet.getType().getId()));
220	        petRepository.save(pet);
221	    }
222	
223	    @Override
224	    @Transactional
225	    public void saveVisit(Visit visit) throws DataAccessException {
226	        visitRepository.save(visit);
227	
228	    }
229	
230	    @Override
231	    @Transactional(readOnly = true)
232	    public Collection<Vet> findVets() throws DataAccessException {
233	        return vetRepository.findAll();
234	    }
235	
236	    @Override
237	    @Transactional
238	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
239	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
240	            throw new DuplicateTelephoneException(owner.getTelephone());
241	        }
242	        List<Owner> householdMembers = findHouseholdMembers(owner);
243	        if (!householdMembers.isEmpty() && !sharesHousehold) {
244	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
245	        }
246	        if (owner.getRegistrationDate() == null) {
247	            owner.setRegistrationDate(LocalDate.now());
248	        }
249	        owner.setCustomerCode(
250	            CustomerCodeGenerator.format(owner.getLastName(), ownerRepository.count() + 1));
251	        if (!householdMembers.isEmpty()) {
252	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
253	        }
254	        ownerRepository.save(owner);
255	        return owner.getHouseholdId();
256	    }
257	
258	    /**
259	     * Assign the stable household identifier to the new owner and to every existing member of the
260	     * household, persisting the members whose identifier changes, and return the shared identifier.
261	     */
262	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
263	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
264	        for (Owner member : householdMembers) {
265	            if (!householdId.equals(member.getHouseholdId())) {
266	                member.setHouseholdId(householdId);
267	                ownerRepository.save(member);
268	            }
269	        }
270	        return householdId;
271	    }
272	
273	    @Override
274	    @Transactional
275	    public void saveOwner(Owner owner) throws DataAccessException {
276	        ownerRepository.save(owner);
277	    }
278	
279	    /**
280	     * Find the existing owners that already share this owner's household, i.e. that have the same last name and
281	     * address compared case-insensitively and with runs of whitespace collapsed.
282	     */
283	    private List<Owner> findHouseholdMembers(Owner owner) {
284	        String address = TextNormalizer.normalize(owner.getAddress());
285	        if (address == null) {
286	            return List.of();
287	        }
288	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
289	            .filter(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())))
290	            .toList();
291	    }
292	
293	    @Override
294	    @Transactional(readOnly = true)
295	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
296	        return ownerRepository.findByLastName(lastName);
297	    }
298	
299	    @Override
300	    @Transactional(readOnly = true)
301	    public Collection<Visit> findVisitsByPetId(int petId) {
302	        return visitRepository.findByPetId(petId);
303	    }
304	
305	    @Override
306	    @Transactional(readOnly = true)
307	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
308	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
309	    }
310	
311	    private <T> T findEntityById(Supplier<T> supplier) {
312	        try {
313	            return supplier.get();
314	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
315	            // Just ignore not found exceptions for Jdbc/Jpa realization
316	            return null;
317	        }
318	    }
319	
320	}
