17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Optional;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Converts telephone numbers to canonical E.164 form. Shared by the create-time validation
24	 * constraint and the mapping that stores the value, so both agree on what a valid, stored
25	 * telephone looks like.
26	 *
27	 * <p>A leading {@code '+'} with its country code is kept as given; otherwise the Australian
28	 * country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
29	 * national digits. Spaces, dashes and brackets are ignored. The digits following the
30	 * {@code '+'} must number between 8 and 15 inclusive.
31	 */
32	public final class TelephoneNormalizer {
33	
34	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
35	    private static final String DEFAULT_COUNTRY_CODE = "61";
36	
37	    /** Separators that carry no meaning and are stripped before parsing. */
38	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
39	
40	    private static final int MIN_DIGITS = 8;
41	    private static final int MAX_DIGITS = 15;
42	
43	    private TelephoneNormalizer() {
44	    }
45	
46	    /**
47	     * Convert the given telephone value to E.164 form.
48	     *
49	     * @param telephone the raw telephone value (may be {@code null})
50	     * @return the E.164 string (a {@code '+'} followed by 8 to 15 digits), or
51	     * {@link Optional#empty()} when {@code telephone} is {@code null} or cannot form valid E.164
52	     */
53	    public static Optional<String> toE164(String telephone) {
54	        if (telephone == null) {
55	            return Optional.empty();
56	        }
57	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
58	        String digits;
59	        if (cleaned.startsWith("+")) {
60	            digits = cleaned.substring(1);
61	        } else {
62	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
63	            digits = DEFAULT_COUNTRY_CODE + national;
64	        }
65	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS || !isAllDigits(digits)) {
66	            return Optional.empty();
67	        }
68	        return Optional.of("+" + digits);
69	    }
70	
71	    private static boolean isAllDigits(String value) {
72	        for (int i = 0; i < value.length(); i++) {
73	            char c = value.charAt(i);
74	            if (c < '0' || c > '9') {
75	                return false;
76	            }
77	        }
78	        return true;
79	    }
80	}
