94	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
95	     *
96	     * @param e The {@link Exception} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
99	     */
100	    @ExceptionHandler(Exception.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
103	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
104	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
106	        return ResponseEntity.status(status).body(detail);
107	    }
108	
109	    /**
110	     * Handles {@link DuplicateTelephoneException} raised when creating an owner whose normalized telephone
111	     * number is already used by another owner, returning a 409 Conflict status.
112	     *
113	     * @param e The {@link DuplicateTelephoneException} to be handled
114	     * @param request {@link HttpServletRequest} object referring to the current request.
115	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
116	     */
117	    @ExceptionHandler(DuplicateTelephoneException.class)
118	    @ResponseBody
119	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
120	        logger.warn("Duplicate telephone at {} {}: {}",
121	            request.getMethod(),
122	            request.getRequestURI(),
123	            e.getMessage());
124	        HttpStatus status = HttpStatus.CONFLICT;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles {@link DuplicateHouseholdException} raised when creating an owner whose last name and address
131	     * already belong to another owner (compared case-insensitively with collapsed whitespace), returning a
132	     * 409 Conflict status.
133	     *
134	     * @param e The {@link DuplicateHouseholdException} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
137	     */
138	    @ExceptionHandler(DuplicateHouseholdException.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
141	        logger.warn("Duplicate household at {} {}: {}",
142	            request.getMethod(),
143	            request.getRequestURI(),
144	            e.getMessage());
145	        HttpStatus status = HttpStatus.CONFLICT;
146	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
147	        return ResponseEntity.status(status).body(detail);
148	    }
149	
150	    /**
151	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
152	     * method returns a 404 Not Found status if an entity does not exist.
153	     *
154	     * @param e The {@link DataIntegrityViolationException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
157	     */
158	    @ExceptionHandler(DataIntegrityViolationException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
161	        logger.warn("Data integrity violation at {} {}: {}",
162	            request.getMethod(),
163	            request.getRequestURI(),
164	            e.getMessage());
165	        logger.debug("Data integrity violation stacktrace", e);
166	        HttpStatus status = HttpStatus.NOT_FOUND;
167	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles exception thrown by Bean Validation on controller methods parameters
173	     *
174	     * @param e The {@link MethodArgumentNotValidException} to be handled
175	     * @param request {@link HttpServletRequest} object referring to the current request.
176	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
177	     */
178	    @ExceptionHandler(MethodArgumentNotValidException.class)
179	    @ResponseBody
180	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
181	        HttpStatus status = HttpStatus.BAD_REQUEST;
182	        BindingErrorsResponse errors = new BindingErrorsResponse();
183	        BindingResult bindingResult = e.getBindingResult();
184	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
185	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
186	            .map(FieldError::getField)
187	            .distinct()
188	            .toList());
189	        if (bindingResult.hasErrors()) {
190	            errors.addAllErrors(bindingResult);
191	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
192	                .map(fieldError -> {
193	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
194	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
195	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
196	                        fieldError.getField(),
197	                        defaultMessage,
198	                        rejectedValue);
199	                    return new ValidationMessageDto(message)
200	                        .putAdditionalProperty("field", fieldError.getField())
201	                        .putAdditionalProperty("rejectedValue", rejectedValue)
202	                        .putAdditionalProperty("defaultMessage", defaultMessage);
203	                })
204	                .toList();
205	            logger.debug("Validation error at {} {}: {}",
206	                request.getMethod(),
207	                request.getRequestURI(),
208	                bindingResult.getFieldErrors());
209	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
210	            return ResponseEntity.status(status).body(detail);
211	        }
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	}
